5984	ostOd >= (SELECT MzdObd_DatumOd FROM TabMzdObd WHERE Stav = 1))        and PlatnostDo <= (SELECT MzdObd_DatumDo FROM TabMzdObd WHERE Stav = 1))       and Typ = 4 and (_HPP = 1 or _DPP = 1)      END   --------------------------------------------------------------------------------------------------------   -- Jirka - označení platebních příkazů které byly exportovány do souboru          -   --------------------------------------------------------------------------------------------------------   if @CommandText='Realizuj'    begin    IF OBJECT_ID('tempdb..##GlobTempTablePPtuz') IS NOT NULL     begin     UPDATE TabPlatTuz SET PocetExportu=1 WHERE PocetExportu=0 AND ID IN (select IDhlavPP from ##GlobTempTablePPtuz where Autor=SUSER_NAME())    end      GOTO KONEC   end     if @CommandText='RealizujBezMartia'    begin    IF OBJECT_ID('tempdb..##GlobTempTablePPtuz') IS NOT NULL    begin     UPDATE TabPlatTuz SET PocetExportu=1 WHERE PocetExportu=0 and autor<>'Martia' AND ID IN (select IDhlavPP from ##GlobTempTablePPtuz where Autor=SUSER_NAME())    end      GOTO KONEC   end     --------------------------------------------------------------------------------------------------------   -- Jirka _  složení return stringu                    -   --------------------------------------------------------------------------------------------------------   SELECT     @PayTxt=(RIGHT('000000' + convert(nvarchar,@PoradCislo),6)       --Cislo radky (6 mist)    + '11'                    --11 = druh plat styku CNB    + convert(nvarchar,getdate(),12)             --Datum vytvoreni YYMMDD    + '5500'                   --Kod banky (Raif. = 5500)    + '   '                    --3 mezery    + Ustav.KodUstavu                 --Kod banky prijemce    + '   '                       --3 mezery    + RIGHT('00000000000000' + convert(nvarchar,(Convert(int,(Pol.Castka * 100)))),15) --Castka * 100 na 15mist    + convert(nvarchar,Hlav.DatumSplatnosti,12)           --Datum splatnosti YYMMDD    + RIGHT('0000000000' + Pol.KonstantniSymbol,10)          --Konstantni symbol 10mist    + RIGHT('0000000000' + Pol.VariabilniSymbol,10)          --Variabilni symbol 10mist    + RIGHT('0000000000' + Pol.SpecifickySymbol,10)          --Specificky symbol 10mist    + '000000'                   --Predcisli uctu klienta 6mist    + RIGHT('000000000' + convert(nvarchar,BankSpojKlient.CisloUctu),10)    --Cislo uctu klienta 10mist     -- +'!!!'    + case when CHARINDEX('-', BankSpoj.CisloUctu) = 0 then '000000' else RIGHT('0000000000' + substring(BankSpoj.CisloUctu, 1, CHARINDEX('-', BankSpoj.CisloUctu)-1),6) end   --Predcisli uctu prijemce 6mist     -- +'!!!'    + case when CHARINDEX('-', BankSpoj.CisloUctu) = 0 then RIGHT(5984	ostOd >= (SELECT MzdObd_DatumOd FROM TabMzdObd WHERE Stav = 1))        and PlatnostDo <= (SELECT MzdObd_DatumDo FROM TabMzdObd WHERE Stav = 1))       and Typ = 4 and (_HPP = 1 or _DPP = 1)      END   --------------------------------------------------------------------------------------------------------   -- Jirka - označení platebních příkazů které byly exportovány do souboru          -   --------------------------------------------------------------------------------------------------------   if @CommandText='Realizuj'    begin    IF OBJECT_ID('tempdb..##GlobTempTablePPtuz') IS NOT NULL     begin     UPDATE TabPlatTuz SET PocetExportu=1 WHERE PocetExportu=0 AND ID IN (select IDhlavPP from ##GlobTempTablePPtuz where Autor=SUSER_NAME())    end      GOTO KONEC   end     if @CommandText='RealizujBezMartia'    begin    IF OBJECT_ID('tempdb..##GlobTempTablePPtuz') IS NOT NULL    begin     UPDATE TabPlatTuz SET PocetExportu=1 WHERE PocetExportu=0 and autor<>'Martia' AND ID IN (select IDhlavPP from ##GlobTempTablePPtuz where Autor=SUSER_NAME())    end      GOTO KONEC   end     --------------------------------------------------------------------------------------------------------   -- Jirka _  složení return stringu                    -   --------------------------------------------------------------------------------------------------------   SELECT     @PayTxt=(RIGHT('000000' + convert(nvarchar,@PoradCislo),6)       --Cislo radky (6 mist)    + '11'                    --11 = druh plat styku CNB    + convert(nvarchar,getdate(),12)             --Datum vytvoreni YYMMDD    + '5500'                   --Kod banky (Raif. = 5500)    + '   '                    --3 mezery    + Ustav.KodUstavu                 --Kod banky prijemce    + '   '                       --3 mezery    + RIGHT('00000000000000' + convert(nvarchar,(Convert(int,(Pol.Castka * 100)))),15) --Castka * 100 na 15mist    + convert(nvarchar,Hlav.DatumSplatnosti,12)           --Datum splatnosti YYMMDD    + RIGHT('0000000000' + Pol.KonstantniSymbol,10)          --Konstantni symbol 10mist    + RIGHT('0000000000' + Pol.VariabilniSymbol,10)          --Variabilni symbol 10mist    + RIGHT('0000000000' + Pol.SpecifickySymbol,10)          --Specificky symbol 10mist    + '000000'                   --Predcisli uctu klienta 6mist    + RIGHT('000000000' + convert(nvarchar,BankSpojKlient.CisloUctu),10)    --Cislo uctu klienta 10mist     -- +'!!!'    + case when CHARINDEX('-', BankSpoj.CisloUctu) = 0 then '000000' else RIGHT('0000000000' + substring(BankSpoj.CisloUctu, 1, CHARINDEX('-', BankSpoj.CisloUctu)-1),6) end   --Predcisli uctu prijemce 6mist     -- +'!!!'    + case when CHARINDEX('-', BankSpoj.CisloUctu) = 0 then RIGHT(char,Hlav.ID)  ,10)                                           --VS klienta (blbe se paruje, protoze je az v doplnujicich informacich a v EDI by s tim bylo moc prace)    + '02'                       --Format cisla uctu 01=libovolny, 02=IBAN    + '02'                       --uctovani platby 01=Bezna platba ZPS, 02=Europlatba    + Left('                                                                                                                                        ',123)    +  LEFT(isnull(UstavPrij.SWIFTUstavu,'') + '              ',11)         --SWIFT prijemce    + '000000'                      --Predcisli uctu klienta 6mist    + convert(nvarchar,Hlav.DatumSplatnosti,12))             --Datum splatnosti YYMMDD    ,@IDPPZahr=Hlav.ID   FROM TabPlatZahr Hlav     LEFT OUTER JOIN TabPenezniUstavy Ustav ON Hlav.IDBankUstavuPlatce=Ustav.ID     LEFT OUTER JOIN TabBankSpojeni BankSpPlatce ON Hlav.IDBankSpojeniPlatce=BankSpPlatce.ID     LEFT OUTER JOIN TabPenezniUstavy UstavPrij ON Hlav.IDBankUstavuPrijemce=UstavPrij.ID     LEFT OUTER JOIN TabZeme ZemeUstavPrij ON substring(UstavPrij.SWIFTUstavu,5,2)=ZemeUstavPrij.ISOKod     LEFT OUTER JOIN TabBankSpojeni BankSpPrij ON Hlav.IDBankSpojeniPrijemce=BankSpPrij.ID     LEFT OUTER JOIN TabCisOrg OrgPrij ON  BankSpPrij.IDOrg = OrgPrij.ID      -- Jirka 10_10_2016 špatné dosazení názvu země pro pozici 263 (Adresa prijemce Stat (dle ISO)).      --původně : LEFT OUTER JOIN TabZeme ZemeOrgPrij ON  substring(UstavPrij.SWIFTUstavu,5,2)=ZemeOrgPrij.ISOKod     LEFT OUTER JOIN TabZeme ZemeOrgPrij ON  BankSpPrij.CilovaZeme=ZemeOrgPrij.ISOKod   WHERE     Hlav.RealizaceExport = 0 AND Hlav.DatumVystaveni > (Getdate() - 8) AND Hlav.ID=@ID   ORDER BY Hlav.id     --uložim si cestu k souboru plat.příkazu do PP Zahr   IF @IDPPZahr IS NOT NULL AND isnull(@PathPayFile,'')<>''   BEGIN    --dva stupně kontroly    IF EXISTS(SELECT 1 FROM TabPlatZahr_EXT WHERE ID=@IDPPZahr)     IF EXISTS(SELECT 1 FROM TabPlatZahr_EXT WHERE ID=@IDPPZahr AND _PathPayFile<>@PathPayFile)      UPDATE TabPlatZahr_EXT SET _PathPayFile=@PathPayFile WHERE ID=@IDPPZahr     ELSE PRINT '...'    ELSE INSERT INTO TabPlatZahr_EXT (ID,_PathPayFile) VALUES (@IDPPZahr,@PathPayFile)    END      --zápis id hlavičky PP do globTempTable   IF OBJECT_ID('tempdb..##GlobTempTablePPzahr') IS NULL CREATE TABLE ##GlobTempTablePPzahr( Autor nvarchar(128), IDhlavPP INT)    INSERT INTO ##GlobTempTablePPzahr(Autor,IDhlavPP) VALUES(SUSER_NAME(),@IDPPZahr)     --založit záznam v AvizoPol   --IF suser_name() = 'Jiri' -- bacha jirka   BEGIN    --založit záznam v AvizoPol    insert into EC_PP_Aviz␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀oPol (TypPP,IDOrg,IDBankSpojeni,ID_PolPP,Zobrazeno,ID_HlavPP)    select 2,BankSpPrij.IDOrg,Hlav.IDBankSpojeniPrijemce,Pol.ID,0,Hlav.ID    FROM TabPlatZahrDetail Pol     LEFT OUTER JOIN TabPlatZahr Hlav on Pol.IDHlavaPPZ=Hlav.ID     LEFT OUTER JOIN TabPenezniUstavy Ustav ON Hlav.IDBankUstavuPlatce=Ustav.ID     LEFT OUTER JOIN TabBankSpojeni BankSpPlatce ON Hlav.IDBankSpojeniPlatce=BankSpPlatce.ID     LEFT OUTER JOIN TabPenezniUstavy UstavPrij ON Hlav.IDBankUstavuPrijemce=UstavPrij.ID     LEFT OUTER JOIN TabZeme ZemeUstavPrij ON substring(UstavPrij.SWIFTUstavu,5,2)=ZemeUstavPrij.ISOKod     LEFT OUTER JOIN TabBankSpojeni BankSpPrij ON Hlav.IDBankSpojeniPrijemce=BankSpPrij.ID     LEFT OUTER JOIN TabCisOrg OrgPrij ON  BankSpPrij.IDOrg = OrgPrij.ID      LEFT OUTER JOIN TabCisOrg_EXT OrgExtPrij ON  OrgPrij.ID = OrgExtPrij.ID      LEFT OUTER JOIN TabZeme ZemeOrgPrij ON  BankSpPrij.CilovaZeme=ZemeOrgPrij.ISOKod    WHERE     Hlav.RealizaceExport = 0 AND Hlav.DatumVystaveni > (Getdate() - 8) AND Hlav.ID=@ID AND OrgExtPrij._PlatPrikazyAvizo=1    ORDER BY Hlav.id   END     --u každé faktury nastavíme , že _NavrhPlatby=0   UPDATE TDZext   SET TDZext._NavrhPlatby=0   FROM TabPlatZahrDetail Orig    LEFT OUTER JOIN TabPlatZahrDetail_EXT as EXT ON Orig.ID=EXT.ID    LEFT OUTER JOIN TabDokladyZbozi as TDZ ON TDZ.ID=EXT._IDFak AND TDZ.DruhPohybuZbo>=18 AND TDZ.DruhPohybuZbo<=19 AND TDZ.PoradoveCislo>=0 AND TDZ.RadaDokladu in('500','510','520','530','540','560','590','501','511','521','531','541','561','591')    LEFT OUTER JOIN TabDokladyZbozi_ext as TDZext ON TDZext.ID = TDZ.ID   WHERE Orig.IDHlavaPPZ=@ID     --------------------------------------------------------------------------------------------------------   -- Jirka _  odstranění @lf @cr z stringu                  -   --------------------------------------------------------------------------------------------------------   SELECT @PayTxt=replace(replace(@PayTxt, @cr, ' '), @lf, ' ')     --------------------------------------------------------------------------------------------------------   -- Jirka _  konec                        -   --------------------------------------------------------------------------------------------------------   KONEC:      --pokud šlo o realizaci exportu , smaž záznamy z temp table podle autora    if @CommandText='RealizujBezMartia' or @CommandText='Realizuj'    begin     IF OBJECT_ID('tempdb..##GlobTempTablePPzahr') IS NOT NULL      delete from ##GlobTempTablePPzahr where Autor = suser_name()    end    END␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀␀